css:
.br { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: 2rem; }
.br a { text-decoration: none; }
.br__btn { display: inline-flex; align-items: center; justify-content: center; padding: .85em 1.5em; border: 2px solid currentColor; border-radius: 999px; font-weight: 700; font-size: 1.02rem; line-height: 1.1; color: var(--os-color-heading); transition: background-position .4s, background-color .2s, color .2s; }
.br__btn--p { border-color: transparent; color: #15261a; background: linear-gradient(100deg, var(--bff-btn-a, #a7c25a), var(--bff-btn-b, #f2cb4a) 60%, var(--bff-btn-a, #a7c25a)) 0 0 / 220% 100%; }
.br__btn--p:hover { background-position: 100% 0; }
.br__btn:not(.br__btn--p):hover { background: var(--os-color-heading); color: var(--os-color-background); }
@media (prefers-reduced-motion: reduce) { .br__btn { transition: none; } }
